declare(strict_types=1); namespace OCA\FolderTemplate\Controller; use OCP\AppFramework\Controller; use OCP\AppFramework\Http\DataResponse; use OCP\AppFramework\Http\Attribute\NoAdminRequired; use OCP\Files\File; use OCP\Files\Folder; use OCP\Files\IRootFolder; use OCP\Files\Node; use OCP\IConfig; use OCP\IRequest; use OCP\IUserSession; use Psr\Log\LoggerInterface; class TemplateController extends Controller { private const CONFIG_APP = 'foldertemplate'; private const CONFIG_KEY_TEMPLATES = 'templates'; public function __construct( string $appName, IRequest $request, private IRootFolder $rootFolder, private IUserSession $userSession, private IConfig $config, private LoggerInterface $logger ) { parent::__construct($appName, $request); } private function getUserId(): ?string { return $this->userSession->getUser()?->getUID(); } private function getUserFolder(): Folder { $userId = $this->getUserId(); if ($userId === null) { throw new \RuntimeException('User not authenticated'); } return $this->rootFolder->getUserFolder($userId); } #[NoAdminRequired] public function getTemplates(): DataResponse { $userId = $this->getUserId(); if ($userId === null) { return new DataResponse(['success' => false, 'error' => '未ログインです'], 401); } $raw = $this->config->getUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, '[]'); $templates = json_decode($raw, true) ?: []; return new DataResponse([ 'success' => true, 'templates' => $templates ]); } #[NoAdminRequired] public function createTemplate(): DataResponse { $userId = $this->getUserId(); if ($userId === null) { return new DataResponse(['success' => false, 'error' => '未ログインです'], 401); } $folderPath = (string)$this->request->getParam('folderPath'); $templateName = trim((string)$this->request->getParam('name', '')); $targetFileId = $this->request->getParam('fileId'); if (empty($folderPath) && empty($targetFileId)) { return new DataResponse(['success' => false, 'error' => '対象フォルダが指定されていません'], 400); } try { $userFolder = $this->getUserFolder(); $sourceNode = null; if (!empty($targetFileId)) { $nodes = $userFolder->getById((int)$targetFileId); if (!empty($nodes) && $nodes[0] instanceof Folder) { $sourceNode = $nodes[0]; } } if ($sourceNode === null && !empty($folderPath)) { $relPath = ltrim($folderPath, '/'); if ($userFolder->nodeExists($relPath)) { $node = $userFolder->get($relPath); if ($node instanceof Folder) { $sourceNode = $node; } } } if (!($sourceNode instanceof Folder)) { return new DataResponse(['success' => false, 'error' => '指定されたフォルダが見つかりません: ' . $folderPath], 404); } $originalFolderName = $sourceNode->getName(); if (empty($templateName)) { $templateName = $originalFolderName; } $templateId = 'tpl_' . bin2hex(random_bytes(6)); $raw = $this->config->getUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, '[]'); $templates = json_decode($raw, true) ?: []; $newTemplate = [ 'id' => $templateId, 'name' => $templateName, 'originalFolderName' => $originalFolderName, 'fileId' => $sourceNode->getId(), 'sourcePath' => $sourceNode->getPath(), 'createdAt' => time() ]; $templates[] = $newTemplate; $this->config->setUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, json_encode($templates)); return new DataResponse([ 'success' => true, 'template' => $newTemplate, 'templates' => $templates ]); } catch (\Throwable $e) { $this->logger->error('Failed to create template: ' . $e->getMessage(), ['exception' => $e]); return new DataResponse(['success' => false, 'error' => 'テンプレート作成に失敗しました: ' . $e->getMessage()], 500); } } #[NoAdminRequired] public function updateTemplate(string $id): DataResponse { $userId = $this->getUserId(); if ($userId === null) { return new DataResponse(['success' => false, 'error' => '未ログインです'], 401); } $newName = trim((string)$this->request->getParam('name', '')); if (empty($newName)) { return new DataResponse(['success' => false, 'error' => '新しいテンプレート名を入力してください'], 400); } $raw = $this->config->getUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, '[]'); $templates = json_decode($raw, true) ?: []; $found = false; foreach ($templates as &$t) { if ($t['id'] === $id) { $t['name'] = $newName; $found = true; break; } } if (!$found) { return new DataResponse(['success' => false, 'error' => 'テンプレートが見つかりません'], 404); } $this->config->setUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, json_encode($templates)); return new DataResponse([ 'success' => true, 'templates' => $templates ]); } #[NoAdminRequired] public function deleteTemplate(string $id): DataResponse { $userId = $this->getUserId(); if ($userId === null) { return new DataResponse(['success' => false, 'error' => '未ログインです'], 401); } $raw = $this->config->getUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, '[]'); $templates = json_decode($raw, true) ?: []; $newTemplates = []; $deleted = null; foreach ($templates as $t) { if ($t['id'] === $id) { $deleted = $t; } else { $newTemplates[] = $t; } } if ($deleted === null) { return new DataResponse(['success' => false, 'error' => 'テンプレートが見つかりません'], 404); } $this->config->setUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, json_encode($newTemplates)); return new DataResponse([ 'success' => true, 'templates' => $newTemplates ]); } #[NoAdminRequired] public function createFromTemplate(?string $templateId = null, ?string $targetDir = null): DataResponse { $userId = $this->getUserId(); if ($userId === null) { return new DataResponse(['success' => false, 'error' => '未ログインです'], 401); } $templateId = $templateId ?: (string)$this->request->getParam('templateId'); $targetDir = $targetDir ?: (string)$this->request->getParam('targetDir', '/'); if (empty($templateId)) { return new DataResponse(['success' => false, 'error' => 'テンプレートIDが指定されていません'], 400); } $raw = $this->config->getUserValue($userId, self::CONFIG_APP, self::CONFIG_KEY_TEMPLATES, '[]'); $templates = json_decode($raw, true) ?: []; $template = null; foreach ($templates as $t) { if ($t['id'] === $templateId) { $template = $t; break; } } if ($template === null) { return new DataResponse(['success' => false, 'error' => 'テンプレートが見つかりません'], 404); } $newFolder = null; try { $userFolder = $this->getUserFolder(); $sourceNode = null; if (!empty($template['fileId'])) { try { $nodes = $userFolder->getById((int)$template['fileId']); if (!empty($nodes) && $nodes[0] instanceof Folder) { $sourceNode = $nodes[0]; } } catch (\Throwable $ignored) {} } if ($sourceNode === null && !empty($template['sourcePath'])) { $relSource = ltrim($template['sourcePath'], '/'); if ($userFolder->nodeExists($relSource)) { $candidate = $userFolder->get($relSource); if ($candidate instanceof Folder) { $sourceNode = $candidate; } } } if (!($sourceNode instanceof Folder)) { return new DataResponse([ 'success' => false, 'error' => 'テンプレート元のフォルダが見つかりませんでした。\n（元フォルダが削除された可能性があります）' ], 404); } $relTargetDir = ltrim($targetDir, '/'); $targetParent = empty($relTargetDir) ? $userFolder : $userFolder->get($relTargetDir); if (!($targetParent instanceof Folder)) { return new DataResponse(['success' => false, 'error' => '展開先ディレクトリが見つかりません'], 404); } $baseName = $sourceNode->getName() ?: ($template['originalFolderName'] ?: $template['name']); $finalName = $baseName; $counter = 1; while ($targetParent->nodeExists($finalName)) { $counter++; $finalName = "{$baseName} ({$counter})"; } $newFolder = $targetParent->newFolder($finalName); $this->copyRecursively($sourceNode, $newFolder); return new DataResponse([ 'success' => true, 'createdFolderName' => $finalName, 'path' => $newFolder->getPath(), 'fileId' => $newFolder->getId() ]); } catch (\Throwable $e) { if ($newFolder instanceof Folder) { try { $newFolder->delete(); } catch (\Throwable $cleanupErr) {} } $this->logger->error('Failed to instantiate folder from template: ' . $e->getMessage(), ['exception' => $e]); return new DataResponse(['success' => false, 'error' => 'テンプレートからの生成に失敗しました: ' . $e->getMessage()], 500); } } private function copyRecursively(Folder $source, Folder $target): void { foreach ($source->getDirectoryListing() as $node) { $nodeName = $node->getName(); if ($node instanceof Folder) { if (!$target->nodeExists($nodeName)) { $newSub = $target->newFolder($nodeName); } else { $newSub = $target->get($nodeName); } $this->copyRecursively($node, $newSub); } else if ($node instanceof File) { if ($target->nodeExists($nodeName)) { try { $target->get($nodeName)->delete(); } catch (\Throwable $ignored) {} } try { $node->copy($target->getPath() . '/' . $nodeName); } catch (\Throwable $copyErr) { $stream = $node->fopen('r'); if ($stream !== false) { $target->newFile($nodeName, $stream); if (is_resource($stream)) { fclose($stream); } } else { $target->newFile($nodeName, $node->getContent()); } } } } } }